 for(let j=0;j<budget;j++){const id=list[j],f=FURNISHINGS[id];if([16,18].includes(id)||plan.some(o=>o.visual&&o.furniture===id))continue;const caps={0:10,1:5,2:9,3:1,4:1,5:6,6:3,7:4,8:9,9:4,10:6,11:12,12:5,13:6,14:10,15:4,17:8,19:3,20:5,21:3,22:4,23:5};if(plan.filter(o=>o.furniture===id).length>=(caps[id]||10))continue;const zones=[[.1,.05],[.5,0],[1,.7],[0,.65],[1,0],[.65,.5],[0,.1],[1,.4],[.15,.4],[0,.5],[1,.1],[.15,.2],[1,.9],[0,1],[.8,.6],[.2,.85],[.5,.5],[.8,.8],[.5,0],[0,.4],[.4,.1],[.7,.6],[.9,.8],[.7,.3]],zone=zones[id];const focus=furnishingFocus(id,kind,box,plan);candidates.sort((a,b)=>{const distance=p=>Math.hypot(p[0]-(focus?.[0]??box.left+zone[0]*(box.right-box.left-f.w+1)),p[1]-(focus?.[1]??box.top+zone[1]*(box.bottom-box.top-f.h+1)));return distance(a)-distance(b);});let done=false;for(const [x,y]of candidates){if(x+f.w-1>box.right||y+f.h-1>box.bottom)continue;let ok=true;for(let yy=y;yy<y+f.h;yy++)for(let xx=x;xx<x+f.w;xx++)if(grid[yy]?.[xx]!=='.'||reserved.has(xx+','+yy)||occupied.has(xx+','+yy))ok=false;if(ok&&plan.some(o=>![16,18].includes(o.furniture)&&x<o.footprint.x+o.footprint.w+1&&x+f.w+1>o.footprint.x&&y<o.footprint.y+o.footprint.h+1&&y+f.h+1>o.footprint.y))ok=false;if(ok&&place(id,x,y,f.w,f.h)){done=true;break;}}}
 if(area>350){const communal=['inn','mess','assembly'].includes(kind),extras=communal?Math.min(3,Math.floor(area/110)):Math.min(12,Math.floor((area-250)/85)),slots=[[.22,.38],[.65,.4],[.35,.78],[.8,.82],[.15,.9],[.85,.12],[.4,.15],[.48,.56],[.25,.62],[.76,.25],[.5,.85],[.12,.42]];for(let i=0;i<extras;i++){const k=communal?(kits.find(k=>k.visual==='dining')||kits[0]):kits[i%kits.length];if([0,11].includes(k.id)&&plan.filter(o=>o.furniture===k.id).length>=Math.min(5,Math.max(2,Math.floor(area/140))))continue;if(k.id===8&&plan.filter(o=>o.furniture===8).length>=Math.max(2,Math.min(6,Math.floor(area/180))))continue;const z=slots[i],kit={...k,label:k.label+' · '+(i+2)};const publicZone=architectureProgram.zones.find(z=>z.role==='public'),focus=communal?[publicZone.x+publicZone.w*(.15+(i%2)*.5),publicZone.y+publicZone.h*(.25+Math.floor(i/2)*.4)]:[box.left+z[0]*(box.right-box.left),box.top+z[1]*(box.bottom-box.top)];placeKit(kit,focus);}}
 for(let x=box.left+1;x<=box.right-1;x+=Math.max(3,Math.floor((box.right-box.left)/3)))place(18,x,Math.max(0,box.top-1),1,1,true);const focus=plan.find(o=>[5,21,8,7].includes(o.furniture))?.footprint,target=focus?[focus.x,focus.y]:[(box.left+box.right)/2,(box.top+box.bottom)/2];const rugSites=box.pts.filter(([x,y])=>[0,1].every(dy=>[0,1,2].every(dx=>base[y+dy]?.[x+dx]==='.'))).sort((a,b)=>Math.hypot(a[0]-target[0],a[1]-target[1])-Math.hypot(b[0]-target[0],b[1]-target[1]));if(rugSites[0])place(16,rugSites[0][0],rugSites[0][1],3,2,true);
 s.floor=grid.map(r=>r.join(''));for(const o of s.objects)if(o.type==='camp')o.label='Resting place';s.household={signature,kind,box:{left:box.left,top:box.top,right:box.right,bottom:box.bottom},floorBase:architectureProgram.floorBase,partitions,architectureProgram,furnishings:plan,version:PLAN_VERSION,composition:{realism:REALISM_REVISION,program:kind,replacedObstacleBlocks:oldBlocks.length}};
