export function householdInteraction(w,o){if(o.type!=='furnishing')return false;const record=w.state.household??={examined:[],opened:[]};if(!record.examined.includes(o.householdId))record.examined.push(o.householdId);record.openFurniture??=[];const choices=[['Look closer',()=>w.text(o.detail)]];if([1,2,7,10,12,19,20].includes(o.furniture)&&!o.supply){const open=record.openFurniture.includes(o.householdId);choices.push([open?'Close it carefully':'Open and examine it',()=>{if(open)record.openFurniture=record.openFurniture.filter(id=>id!==o.householdId);else record.openFurniture.push(o.householdId);w.text(open?'You close it carefully and leave everything in its place.':o.detail+'\nYou leave the contents where their owner can find them.');}]);}if(o.supply)choices.push([record.opened.includes(o.householdId)?'The shared compartment is empty':'Take a road remedy',()=>{if(record.opened.includes(o.householdId))return w.text('The compartment is empty. The note asks you to leave the other supplies for the next traveller.');record.opened.push(o.householdId);w.state.items[o.supply]=(w.state.items[o.supply]||0)+1;w.text('You take the remedy offered for travellers.\nSupplies: 1 Moss wrap.');}]);if([3,4].includes(o.furniture))choices.push(['Warm your hands',()=>{for(const h of w.activeHeroes)h.strain=Math.max(0,(h.strain||0)-8);w.text('The heat eases the ache in your hands. Outside, the day is still waiting.');}]);choices.push(['Leave it as it is',()=>{}]);w.choose(o.label+'\n'+o.text,choices);return true;}
export function settleHouseholdPosition(w){for(const d of Object.values(w.state.physicalLore?.dropped||{})){const room=w.scenes.get(d?.scene);if(!room||!Array.isArray(d.xy)||room.floor[d.xy[1]]?.[d.xy[0]]==='.')continue;const free=[];room.floor.forEach((r,y)=>[...r].forEach((v,x)=>{if(v==='.')free.push([x,y]);}));free.sort((a,b)=>Math.hypot(a[0]-d.xy[0],a[1]-d.xy[1])-Math.hypot(b[0]-d.xy[0],b[1]-d.xy[1]));if(free[0])d.xy=free[0];}if(w.walkable(w.state.x,w.state.y))return;const s=w.scene,candidates=[];s.floor.forEach((r,y)=>[...r].forEach((v,x)=>{if(v==='.')candidates.push([x,y]);}));candidates.sort((a,b)=>Math.hypot(a[0]+.5-w.state.x,a[1]+.5-w.state.y)-Math.hypot(b[0]+.5-w.state.x,b[1]+.5-w.state.y));if(candidates[0]){w.state.x=candidates[0][0]+.5;w.state.y=candidates[0][1]+.5;}}
